vector<vector<int>> adj;
vector<Edge> edges;

void addEdge(int u, int v, int cap) {
    adj[u].push_back(edges.size());
    edges.emplace_back(u, v, 0, cap);
    adj[v].push_back(edges.size());
    edges.emplace_back(v, u, 0, 0);
}

int ptr[1001], dist[1001];

bool bfs() {
    memset(dist, -1, sizeof(dist));
    dist[s] = 0;
    queue<int> q; q.push(s);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int id : adj[u]) {
            int v = edges[id].v;
            if (dist[v] == -1 && edges[id].flow < edges[id].capacity) {
                dist[v] = dist[u] + 1;
                q.push(v);
                if (v == t) return true;
            }
        }
    }
    return false;
}

long long augment(int u, long long flow) {
    if (flow == 0 || u == t) return flow;
    for (; ptr[u] < adj[u].size(); ++ptr[u]) {
        int id = adj[u][ptr[u]];
        int v = edges[id].v;
        if (dist[v] == dist[u] + 1 && edges[id].flow < edges[id].capacity) {
            long long pushed = augment(v, min(flow, (long long)(edges[id].capacity - edges[id].flow)));
