                edges[id].flow += pushed;
                edges[id ^ 1].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

long long maxFlow() {
    long long totalFlow = 0;
    while (bfs()) {
        memset(ptr, 0, sizeof(ptr));
        while (long long pushed = augment(s, LLONG_MAX))
